        for (self.layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
    }
};

pub fn neuronUpdate(
    weights: []const f64,
    biases: []const f64,
    input: []const f64,
    dt: f64,
    state: *NeuronState,
) void {
    var sums = state.allocator.alloc(f64, NUM_NEURONS) catch unreachable;
    defer state.allocator.free(sums);

    var i: usize = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        sums[i] = 0.0;
        var j: usize = 0;
        while (j < NUM_NEURONS) : (j += 1) {
            const w = weights[i * NUM_NEURONS + j];
            sums[i] += input[j] * w * state.conductance[i];
        }
        sums[i] += biases[i];
    }

    var new_pot = state.allocator.alloc(f64, NUM_NEURONS) catch unreachable;
    defer state.allocator.free(new_pot);

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        if (state.potential[i] >= THRESHOLD) {
            new_pot[i] = RESET_POT;
        } else if (state.refractory[i] > 0) {
            new_pot[i] = RESET_POT;
        } else {
            const decay = state.potential[i] / TIME_CONSTANT * dt / state.conductance[i] * state.mem_res[i];
            new_pot[i] = state.potential[i] + sums[i] - decay;
        }
    }

    var spikes = state.allocator.alloc(bool, NUM_NEURONS) catch unreachable;
    defer state.allocator.free(spikes);

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        spikes[i] = new_pot[i] >= THRESHOLD;
    }

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        const spike_contrib: f64 = if (spikes[i]) 0.1 * state.conductance[i] else 0.0;
        state.diffusion[i] += DIFFUSION_RATE * spike_contrib + new_pot[i] * dt * DIFFUSION_RATE;
    }

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        state.conductance[i] = if (spikes[i]) @min(state.conductance[i] * 1.2, 2.0) else state.conductance[i];
    }

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        state.mem_res[i] = @exp(-new_pot[i]) * MEMRISTOR_BASE;
    }

    i = 0;
    while (i < NUM_NEURONS) : (i += 1) {
        state.refractory[i] = if (spikes[i]) REFRACTORY else if (state.refractory[i] > 0) state.refractory[i] - 1 else 0;
    }

    @memcpy(state.potential, new_pot);
}

pub fn slmForward(
    model: *const SlmModel,
    input: []const f64,
    dt: f64,
    output: []f64,
    allocator: Allocator,
) !void {
    var current = try allocator.alloc(f64, NUM_NEURONS);
    defer allocator.free(current);

    @memcpy(current, input[0..NUM_NEURONS]);

    for (model.layers) |layer| {
        var state = try NeuronState.init(allocator);
        defer state.deinit();

        neuronUpdate(layer.weights, layer.biases, current, dt, &state);

        var i: usize = 0;
