    var states = [_]f64{ 1000.0, 0.001, 1.0, 1000.0, 0.001, 1.0 };
    const voltages = [_]f64{ 0.5, -0.5 };

    memristorUpdate(&states, &voltages, 0.01);

    try std.testing.expect(states[0] >= 100.0);
    try std.testing.expect(states[0] <= 10000.0);
