    var potentials = try allocator.alloc(f64, 10);
    defer allocator.free(potentials);
    var diffusions = try allocator.alloc(f64, 10);
    defer allocator.free(diffusions);

    var i: usize = 0;
    while (i < 10) : (i += 1) {
        potentials[i] = @floatFromInt(i);
        diffusions[i] = 0.0;
    }

    diffusiveStep(potentials, diffusions, 0.01, 0.05);

    try std.testing.expect(diffusions[0] != 0.0);
}
